import{SitemapStream,streamToPromise}from"sitemap";import{Readable}from"stream";import{outputFile}from"../common/file-tools.js";import{getGlobalVariables}from"../action/setup-global-variables.js";export async function update(){const{DUMOGU_Domain:e}=process.env,t=new Date,a=[{url:"",changefreq:"daily",priority:1},{url:"about",changefreq:"monthly",priority:.8,lastmod:t},{url:"tags",changefreq:"weekly",priority:.9,lastmod:t},{url:"archive",changefreq:"weekly",priority:.9,lastmod:t},{url:"friendly-link",changefreq:"weekly",priority:.9,lastmod:t}],r=new SitemapStream({hostname:`https://${e}`}),o=await streamToPromise(Readable.from(a).pipe(r)).then(e=>e.toString());await outputFile(getGlobalVariables("sitemapXmlPath"),o)}